import React, { useRef, useState } from "react";
import Webcam from "react-webcam";
import "./CSS/FaceRecognition.css";

const FaceRecognition = () => {
  const webcamRef = useRef(null);
  const [email, setEmail] = useState("");
  const [statusMessage, setStatusMessage] = useState("");
  const [verifying, setVerifying] = useState(false);

  const captureAndVerify = async () => {
    if (!email || !webcamRef.current) {
      setStatusMessage("❌ Please enter email and ensure webcam is active.");
      return;
    }

    const imageSrc = webcamRef.current.getScreenshot();
    if (!imageSrc) {
      setStatusMessage("❌ Failed to capture image.");
      return;
    }

    try {
      setVerifying(true);
      const response = await fetch("http://127.0.0.1:5000/verify-face", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, image: imageSrc }),
      });

      const result = await response.json();
      if (result.success) {
        setStatusMessage("✅ Face verified successfully!");
      } else {
        setStatusMessage("❌ Face verification failed.");
      }
    } catch (err) {
      setStatusMessage("❌ Error verifying face.");
    } finally {
      setVerifying(false);
    }
  };

  return (
    <div className="face-container">
      <h2 className="face-heading">Face Verification</h2>

      <input
        type="email"
        placeholder="Enter your email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className="face-email-input"
      />

      <div className="face-box">
        <Webcam
          audio={false}
          ref={webcamRef}
          screenshotFormat="image/jpeg"
          width={300}
          height={300}
          videoConstraints={{ width: 300, height: 300, facingMode: "user" }}
        />
      </div>

      <button
        onClick={captureAndVerify}
        className="face-button"
        disabled={verifying}
      >
        {verifying ? "Verifying..." : "Verify Face"}
      </button>

      <p className="face-status">{statusMessage}</p>
    </div>
  );
};

export default FaceRecognition;
